nB,CACA,GAAG,MAAOE,aAAP,EAAuB,WAA1B,CAAuC,CACrCtT,MAAMoT,QAAU,+BAAhB,EACA,MACD,CAED;AACA,GAAIK,QAASN,MAAMnO,aAAN,CAAoB,SAApB,EAA+BpC,QAA5C,CAEA,IAAI,GAAIC,GAAE,CAAV,CAAaA,EAAE4Q,OAAOpR,MAAtB,CAA8BQ,GAA9B,CAAmC,CACjC,GAAI0K,OAAUkG,OAAO5Q,CAAP,CAAd,CACI6Q,KAAUnG,MAAMvI,aAAN,CAAoB,eAApB,EAAqCqO,SAArC,CAA+CrF,IAA/C,EADd,CAEIzE,QAAU/L,EAAE,QAAF,CAAY+P,KAAZ,CAFd,CAIA;AACA,GAAIoG,WAAYnW,EAAE,kBAAF,CAAsB+L,OAAtB,EAA+BiF,IAA/B,GAAsCR,IAAtC,EAAhB,CACA,GAAG,SAAS4F,IAAT,CAAcD,SAAd,CAAH,CAA6B,CAC3B,QACD,CAED;AACA/I,cAAciJ,UAAd,CAAyB,CACvBH,IADuB,CAEvBnK,OAFuB,CAGvBH,QAASmE,MAAMuG,YAAN,CAAmB,eAAnB,CAHc,CAIvBxK,OAASC,QAAQ5J,IAAR,CAAa,KAAb,CAJc,CAKvBJ,IAASqL,cAAcmJ,eAAd,CAA8BT,YAA9B,CAA4CI,IAA5C,CALc,CAAzB,CAOD,CACF,CAxCiB,CA0ClB;;;;;KAMAK,gBAAiB,SAAST,YAAT,CAAuBI,IAAvB,CAA6B,CAC5C,KAAMnU,KAAO,0DAAyD+T,cAAgB,IAAK,mBAAkBU,mBAAmBN,IAAnB,CAAyB,OAAMO,KAAKC,KAAL,CAAWD,KAAKE,MAAL,GAAgB,OAA3B,CAAoC,aAAhL,CAEA,KAAMC,WAAY,iDAAmDJ,mBAAmBzU,GAAnB,CAArE,CAEA,MAAO6U,UACR,CAtDiB,CAwDlB;;KAGAP,WAAY,SAAS,CAACtU,GAAD,CAAMmU,IAAN,CAAYtK,OAAZ,CAAqBE,MAArB,CAA6BC,OAA7B,CAAT,CAAgD,CAC1D/L,EAAE,YAAF,CAAgB+L,OAAhB,EAAyBwC,MAAzB,GAEA,GAAIlL,QAAS,GAAb,CAEAoL,MAAM1M,GAAN,EACG2M,IADH,CACQC,KAAO,CACXtL,OAASsL,IAAItL,MAAb,CAEA,GAAGsL,IAAItL,MAAJ,EAAY,GAAf,CAAoB,CAClB,MAAOsL,KAAIqC,IAAJ,EACR,CAFD,IAEO,CACL,MAAOrC,KAAIC,IAAJ,EACR,CACF,CATH,EAUGF,IAVH,CAUQE,MAAQ,CACZ,GAAGvL,QAAQ,GAAX,CAAgB,CACdd,QAAQF,KAAR,CAAcgB,MAAd,CAAsBuL,IAAtB,EACA,MACD,CACD,GAAIC,MAAO,GAAIC,KAAJ,CAAS,CAACF,IAAD,CAAT,CAAiBsH,KAAO,MAAxB,CAAgC,CAAChU,KAAM,YAAP,CAAhC,CAAX,CAEA,GAAIe,IAAK,GAAIC,SAAb,CACAD,GAAG6B,MAAH,CAAU,SAAV,CAAqBgH,MAArB,EACA7I,GAAG6B,MAAH,CAAU,WAAV,CAAuB,QAAvB,EACA7B,GAAG6B,MAAH,CAAU,WAAV,CAAuBtF,OAAOI,OAAP,CAAeS,MAAf,CAAsBgE,SAA7C,EACApB,GAAG6B,MAAH,CAAU,SAAV,CAAqBtF,OAAOI,OAAP,CAAeS,MAAf,CAAsBiE,OAA3C,EACArB,GAAG6B,MAAH,CAAU,MAAV,CAAkB+J,IAAlB,EAEA7O,EAAE8B,IAAF,CAAO,CACLC,IAAK,eAAiB6J,OAAjB,CAA2B,SAD3B,CAELzJ,KAAMc,EAFD,CAGLE,YAAa,KAHR,CAILC,YAAa,KAJR,CAKLlB,KAAM,MALD,CAMLT,QAAS,SAASU,IAAT,CAAc,CACrB,GAAGA,KAAK4C,OAAR,CAAiB,CACfvC,MAAML,KAAK4C,OAAX,CACD,CACDgH,QAAQoF,WAAR,CAAoBhP,KAAKwH,QAAzB,CACD,CAXI,CAAP,EAYI;AACL,CArCH,EAqCM;AACP,CAAC;AAtGgB,CAApB,CAyGA;AACA;AACA,QAAS2D,iBAAT,CAA0B1K,CAA1B,CAA6B,CAC3B,GAAImJ,SAAU/L,EAAE4C,EAAEC,MAAJ,EAAY0K,OAAZ,CAAoB,IAApB,CAAd,CACIsJ,MAAQ7W,EAAE,MAAF,CAAU+L,OAAV,CADZ,CAGInD,YAAc,SAAS/E,KAAT,CAAgB,CAC5BgT,MAAM1I,IAAN,CAAWtK,KAAX,CACD,CALL,CAMIgH,aAAe,UAAW,CACxB,GAAIiM,KAAM/K,QAAQ3B,KAAR,EAAV,CAEA2B,QAAQwB,OAAR,CAAgB,OAAhB,EAAyBzD,IAAzB,CAA8B,IAA9B,EAAoC2D,IAApC,CAAyC,UAAW,CAClDzN,EAAE,IAAF,EAAQ8J,IAAR,CAAc,SAAQgN,GAAI,WAAUA,GAAI,GAAxC,EAA4CvI,MAA5C,EACD,CAFD,CAGD,CAZL,CAaItD,UAAYc,QAAQ/H,IAAR,CAAa,UAAb,CAbhB,CAcImH,gBAAkBY,QAAQgG,QAAR,CAAiB,WAAjB,EAAgC,WAAhC,CAA8C,QAdpE,CAgBA,GAAI1K,KAAM7H,OAAOkD,KAAP,CAAa4E,YAAb,GAA4BC,GAA5B,CAAgC,CAAhC,EAAmCC,aAAnC,CAAiD,QAAjD,CAAV,CACAH,IAAII,SAAJ,CAAgB,EAAhB,CAEAlI,OAAO,EAAC,mBAAD,EACL,OAAQC,OAAOI,OAAP,CAAeS,MAAf,CAAsB6G,YADzB,CAEL,UAAW+D,SAFN,CAGL,gBAAiBE,eAHZ,CAIL,YAAavC,WAJR,CAKL,aAAciC,YALT,CAML,MAAOgM,MAAM1I,IAAN,GAAaqC,IAAb,EANF,EAAP,CAOInJ,GAPJ,EAQA7H,OAAOkD,KAAP,CAAagF,MAAb,EACD","file":"edit.js","sourcesContent":["/** @jsx h */\n'use strict';\nconst {h, Component, render} = window.preact;\n\nvar process = process || {};\nprocess.env = process.env || {};\n\nwindow.MEMLIKE = window.MEMLIKE || {};\nwindow.MEMLIKE.js_edit = {\n  build_date: "2026-05-13T04:07-04:00",\n};\n\n/* global $, window, document, console */\n/* global setTimeout, confirm, alert, fetch */\n/* global navigator, Blob, URL, File, FormData, FileReader, Promise */\n\n$(document).ready(function(){\n  Object.freeze(window.MEMLIKE.course);\n  Object.freeze(window.MEMLIKE.categories_tree);\n  Object.freeze(window.MEMLIKE.localized_languages);\n\n  render(\n    <Edit course={window.MEMLIKE.course} />,\n    document.getElementById('edit-levels'),\n  );\n});\n\n//+--------------------------------------------------------\n//| Render Levels\n//+--------------------------------------------------------\n\nclass CourseSettingsModal extends Component {\n  constructor(props) {\n    super(props);\n\n    this.closeModal = this.closeModal.bind(this);\n    this.deleteCourse = this.deleteCourse.bind(this);\n    this.confirmDelete = this.confirmDelete.bind(this);\n    this.uploadImage = this.uploadImage.bind(this);\n    this.submit = this.submit.bind(this);\n    this.tree = this.tree.bind(this);\n\n    this.state = {\n      confirmDelete: false,\n      isLoading: true,\n      isSubmitting: false,\n      details: {\n        photo: 'https://static.memrise.com/img/400sqf/from/uploads/course_photos/5892033000260320091534.png',\n      },\n      errors: false,\n      success: false,\n    };\n    this.confirmDelCourse = '';\n\n    if (window.MEMLIKE.course_details) {\n      this.state.isLoading = false;\n      this.state.details = window.MEMLIKE.course_details;\n    }\n  }\n\n  componentDidMount() {\n    this.getData();\n  }\n\n  getData() {\n    if (!this.state.isLoading) {\n      return;\n    }\n\n    $.ajax({\n      url: '/ajax/course/' + this.props.course.id + '/' + this.props.course.slug + '/details_edit',\n      type: 'GET',\n      success: function(data){\n        window.MEMLIKE.course_details = data;\n        this.setState({\n          isLoading: false,\n          details: data,\n        });\n      }.bind(this),\n\n      error: function(xhr){\n        console.error(xhr);\n\n        this.setState({\n          isLoading: false,\n        });\n        alert(window.I18N['error']);\n      }.bind(this),\n    });\n  }\n\n  closeModal() {\n    window.modal.close();\n  }\n\n  confirmDelete(e) {\n    this.confirmDelCourse = e.target.value;\n  }\n\n  handleChange(id, e) {\n    this.setState({\n      details: {\n        ...this.state.details,\n        [id]: e.target.value,\n      }\n    });\n  }\n\n  submit(e) {\n    e.preventDefault();\n\n    this.setState({\n      isSubmitting: true,\n      success: false,\n    });\n\n    var fd = new FormData(e.target);\n    //fd.append('csrfmiddlewaretoken', window.MEMLIKE.course.csrftoken)\n\n    $.ajax({\n      url: '/ajax/course/' + this.props.course.id + '/' + this.props.course.slug + '/details_edit',\n      data: fd,\n      processData: false,\n      contentType: false,\n      type: 'POST',\n      success: function(data){\n        var details = window.MEMLIKE.course_details = {...this.state.details, ...data};\n\n        this.setState({\n          errors: false,\n          success: true,\n          details,\n        });\n      }.bind(this),\n\n      error: function(xhr){\n        console.error(xhr);\n\n        if (xhr.status != 400 || !xhr.responseJSON) {\n          alert(window.I18N['error']);\n          return;\n        }\n        var errors = {};\n        xhr.responseJSON.forEach((error) => {\n          if (!error.loc) {\n            return;\n          }\n          var k = error.loc.join('.');\n          errors[k in this.state.details ? k : 'base.' + k] = error.msg;\n        });\n        this.setState({\n          errors,\n        });\n      }.bind(this),\n\n      complete: function() {\n        this.setState({\n          isSubmitting: false,\n        });\n      }.bind(this),\n    });\n  }\n\n  deleteCourse(e) {\n    if (!this.state.confirmDelete) {\n      return this.setState({\n        confirmDelete: true,\n      });\n    }\n    if (this.confirmDelCourse != this.props.course.title) {\n      alert(window.I18N.warn_del_course);\n      return;\n    }\n    var $btn = $(e.target);\n    $btn.attr('disabled', 'disabled').addClass('loading-spinner-before loading-spinner-m');\n\n    $.ajax({\n      url: '/ajax/course/remove',\n      method: 'POST',\n      data: {\n        course_id: this.props.course.id,\n      },\n      headers: {\n        'X-CSRFToken': window.MEMLIKE.course.csrftoken,\n        'X-Referer': window.MEMLIKE.course.referer,\n      },\n      success: function(){\n        window.location.href = '/';\n      },\n      error: function(xhr) {\n        $btn.removeAttr('disabled').removeClass('loading-spinner-before loading-spinner-m');\n\n        alert(window.I18N['error']);\n\n        console.error(xhr);\n      },\n      complete: function() {\n        this.setState({confirmDelete: false});\n      }.bind(this),\n    });\n  }\n\n  uploadImage(e) {\n    var $btn = $(e.target.parentNode);\n    $btn.attr('disabled', 'disabled').addClass('loading-spinner-after loading-spinner-m');\n\n    var files = e.target.files;\n    if (!files.length) {\n      return;\n    }\n\n    var fd = new FormData();\n    fd.append('image_file', files[0]);\n    fd.append('csrfmiddlewaretoken', window.MEMLIKE.course.csrftoken)\n\n    $.ajax({\n      url: '/ajax/course/' + this.props.course.id + '/' + this.props.course.slug + '/picture_upload',\n      data: fd,\n      processData: false,\n      contentType: false,\n      type: 'POST',\n      success: function(data){\n        if(data.message) {\n          alert(data.message);\n        }\n        if(!data.success || !data.image_url) {\n          alert(window.I18N['error'])\n        }\n        this.setState({\n          details: {...this.state.details, photo: data.image_url},\n        });\n      }.bind(this),\n      error: function(xhr){\n        console.error(xhr);\n        alert(window.I18N['error']);\n      },\n      complete: function() {\n        $btn.removeAttr('disabled').removeClass('loading-spinner-after loading-spinner-m');\n      },\n    });\n  }\n\n  tree(list, selected, prefix='') {\n    let children = [];\n\n    for(let i=0; i<list.length; i++) {\n      let item = list[i];\n      let name = window.I18N.categories[item.id].replace('&amp;', '&');\n\n      children.push(\n        <option value={item.id} selected={item.id == selected}>\n          {prefix} {name}\n        </option>\n      );\n      if (item.children && item.children.length > 0) {\n        let subchildren = this.tree(item.children, selected, prefix + '    ');\n\n        subchildren && children.push(...subchildren);\n      }\n    }\n    return children;\n  }\n\n  render() {\n    return <div className=\"vcenter settings course-settings\">\n      <h3>\n        {window.I18N['course_settings']}\n      </h3>\n      <div className=\"form\">\n        {this.state.isLoading ? (\n          <div className=\"nicebox\">\n            <span className=\"loading-spinner\"></span>\n          </div>\n        ) : (\n          <div>\n            {this.state.success && <div className=\"alert alert-success\">{window.I18N['save_success']}</div>}\n            {this.state.errors && <div className=\"alert alert-danger\">{window.I18N['error_400']}</div>}\n            <form className=\"nicebox clearfix form\" onSubmit={this.submit}>\n              <div className=\"form-controls\">\n                <label htmlFor=\"name\">{window.I18N['course_name']}</label>\n                <input\n                  id=\"name\"\n                  name=\"name\"\n                  type=\"text\"\n                  value={this.state.details.name}\n                  onChange={this.handleChange.bind(this, 'name')}\n                  required\n                />\n              </div>\n              {this.state.errors && this.state.errors.name && (\n                <div className=\"alert alert-danger\">{window.I18N['invalid_value']}</div>\n              )}\n              {/* what to learn */}\n              <div className=\"form-controls\">\n                <label htmlFor=\"target\">{window.I18N['course_category']}</label>\n                <select id=\"target\" name=\"target\" required onChange={this.handleChange.bind(this, 'target')}>\n                  {this.tree(window.MEMLIKE.categories_tree, this.state.details.target, '')}\n                </select>\n              </div>\n              {this.state.errors && this.state.errors.source && (\n                <div className=\"alert alert-danger\">{window.I18N['invalid_value']}</div>\n              )}\n              {/* for people that speak */}\n              <div className=\"form-controls\">\n                <label htmlFor=\"source\">{window.I18N['course_language']}</label>\n                <select id=\"source\" name=\"source\" required onChange={this.handleChange.bind(this, 'source')}>\n                  {window.MEMLIKE.localized_languages.map((item) => (\n                    <option\n                      key={item.category_id}\n                      value={item.category_id}\n                      selected={this.state.details.source == item.category_id}\n                    >\n                      {item.localized_name}\n                    </option>\n                  ))}\n                </select>\n              </div>\n              {this.state.errors && this.state.errors.source && (\n                <div className=\"alert alert-danger\">{window.I18N['invalid_value']}</div>\n              )}\n              <div className=\"form-controls\">\n                <label htmlFor=\"tags\">{window.I18N['course_tags']}</label>\n                <input\n                  id=\"tags\"\n                  name=\"tags\"\n                  type=\"text\"\n                  value={this.state.details.tags}\n                  onChange={this.handleChange.bind(this, 'tags')}\n                />\n              </div>\n              {this.state.errors && this.state.errors.tags && (\n                <div className=\"alert alert-danger\">{window.I18N['invalid_value']}</div>\n              )}\n              <div className=\"form-controls\">\n                <label htmlFor=\"description\">{window.I18N['course_description']}</label>\n                <textarea\n                  id=\"description\"\n                  name=\"description\"\n                  rows=\"5\"\n                  cols=\"50\"\n                  value={this.state.details.description}\n                  onChange={this.handleChange.bind(this, 'description')}\n                />\n              </div>\n              {this.state.errors && this.state.errors.description && (\n                <div className=\"alert alert-danger\">{window.I18N['invalid_value']}</div>\n              )}\n              <div className=\"form-controls\">\n                <label htmlFor=\"short_description\">{window.I18N['course_short_description']}</label>\n                <input\n                  id=\"short_description\"\n                  name=\"short_description\"\n                  type=\"text\"\n                  value={this.state.details.short_description}\n                  onChange={this.handleChange.bind(this, 'short_description')}\n                />\n              </div>\n              {this.state.errors && this.state.errors.short_description && (\n                <div className=\"alert alert-danger\">{window.I18N['invalid_value']}</div>\n              )}\n              <input\n                name=\"audio_mode\"\n                type=\"hidden\"\n                value={this.state.details.audio_mode ? '1' : '0'}\n              />\n              <input\n                name=\"course_status\"\n                type=\"hidden\"\n                value={this.state.details.course_status}\n              />\n              <input\n                name=\"csrfmiddlewaretoken\"\n                type=\"hidden\"\n                value={this.state.details.csrfmiddlewaretoken}\n              />\n              <div className=\"btn-group\">\n                <button\n                  className={'btn green ' + (this.state.isSubmitting ? 'loading-spinner-after' : '')}\n                  type=\"submit\"\n                  disabled={this.state.isSubmitting}\n                >\n                  {window.I18N['save']}\n                </button>\n              </div>\n            </form>\n\n            {/* IMAGE */}\n            <div className=\"nicebox\">\n              <h4>{window.I18N.course_picture}</h4>\n              <div className=\"picture\">\n                {this.state.details.photo && <img src={this.state.details.photo} alt=\"\" />}\n              </div>\n              <label className=\"btn\" htmlFor=\"upload-course\">\n                <input type=\"file\" id=\"upload-course\" onChange={this.uploadImage} />\n                {window.I18N.course_picture_upload}\n              </label>\n            </div>\n          </div>\n        )}\n        <div className=\"danger-zone alert alert-danger\">\n          <div>\n            <h4>{window.I18N.delete_course_title}</h4>\n            {this.state.confirmDelete && <div>\n              <p>{window.I18N.confirm_del_course}</p>\n              <input type=\"text\" onChange={this.confirmDelete} autoComplete=\"off\" />\n            </div>}\n          </div>\n          <button className=\"btn danger\" type=\"button\" onClick={this.deleteCourse}>\n            {window.I18N.delete_course}\n          </button>\n        </div>\n      </div>\n\n      <div className=\"btn-group\">\n        <button className=\"btn\" onClick={this.closeModal}>{window.I18N['cancel']}</button>\n      </div>\n    </div>\n  }\n}\n\nclass EditCourseActions extends Component {\n  constructor(props) {\n    super(props);\n    this.addLevel = this.addLevel.bind(this);\n\n    this.state = {\n      isLoading: false,\n    };\n    this.showSettings = false;\n    this.onCloseModal = this.onCloseModal.bind(this);\n    this.toggleSettings = this.toggleSettings.bind(this);\n  }\n\n  addLevel(kind) {\n    this.setState({isLoading: true});\n\n    var data = {\n      course_id: this.props.course.id,\n      kind: kind,\n    };\n    if (kind == 'things') {\n      data.pool_id = this.props.course.last_pool_id;\n    }\n    $.ajax({\n      url: '/ajax/level/add',\n      method: 'POST',\n      data,\n      headers: {\n        'X-CSRFToken': window.MEMLIKE.course.csrftoken,\n        'X-Referer': window.MEMLIKE.course.referer,\n      },\n      success: (data) => {\n        this.props.onLevelAdded && this.props.onLevelAdded(data);\n      },\n      complete: () => {\n        this.setState({isLoading: false});\n      },\n    });\n  }\n\n  onCloseModal() {\n    window.modal.onClose('course-settings', null);\n\n    if(!this.showSettings) {\n      return;\n    }\n    this.showSettings = false;\n  }\n\n  toggleSettings() {\n    this.showSettings = !this.showSettings;\n    if(!this.showSettings) {\n      return;\n    }\n    var div = window.modal.getContainer().get(0).querySelector('.modal');\n    div.innerHTML = '';\n\n    render(<CourseSettingsModal course={this.props.course} />, div);\n    window.modal.reopen();\n    window.modal.onClose('course-settings', this.onCloseModal);\n  }\n\n  render() {\n    return (\n      <div className=\"edit-course-actions clearfix\">\n        <div className=\"actions actions-right\">\n          {this.state.isLoading && <span className=\"loading-spinner left\"></span>}\n\n          <button\n            className=\"settings-btn\"\n            type=\"button\"\n            onClick={this.toggleSettings}\n            title={window.I18N['course_settings']}\n          >\n            <span className=\"ico ico-settings ico-l ico-grey\"></span>\n          </button>\n          <button type=\"button\" className=\"btn\" onClick={() => this.addLevel('multimedia')}>\n            {window.I18N.add_level_multimedia}\n          </button>\n          <button type=\"button\" className=\"btn green\" onClick={() => this.addLevel('things')}>\n            {window.I18N.add_level_things}\n          </button>\n        </div>\n      </div>\n    );\n  }\n}\n\nclass Edit extends Component {\n  constructor(props) {\n    super(props);\n    this.setNewRow = this.setNewRow.bind(this);\n    this.onLevelAdded = this.onLevelAdded.bind(this);\n    this.state = {\n      addedLevels: [],\n    }\n  }\n\n  setNewRow(thingsRowTemplate) {\n    this.thingsRowTemplate = thingsRowTemplate;\n\n    bindEditEvents(thingsRowTemplate);\n  }\n\n  onLevelAdded(data) {\n    if (!data.id) {\n      return;\n    }\n    this.setState({\n      addedLevels: [...this.state.addedLevels, {\n        id: data.id,\n        pool_id: data.pool_id,\n        name: '',\n      }],\n    });\n  }\n\n  render() {\n    var opentab = window.location.hash.match(/#(i|l)_(\\d+)/);\n    var c = 0;\n\n    return <div>\n      {this.props.course.last_pool_id && (\n        <EditCourseActions\n          course={this.props.course}\n          onLevelAdded={this.onLevelAdded}\n        />\n      )}\n      {this.props.course.levels.map((level, i) => {\n        var show = false;\n        if(opentab) {\n          if(opentab[1] == 'i') {\n            show = (i+1 == opentab[2]);\n          } else {\n            show = (level.id == opentab[2]);\n          }\n        }\n        return c++, <EditLevel\n          show={show}\n          index={c}\n          key={i}\n          level={level}\n          setNewRow={this.setNewRow}\n          url={this.props.course['url'] + c}\n          />;\n      })}\n      {this.state.addedLevels.map((level, i) => {\n        return c++, <EditLevel\n          show={true}\n          index={c}\n          key={'a_' + i}\n          level={level}\n          setNewRow={this.setNewRow}\n          url={this.props.course['url'] + c}\n          />;\n      })}\n    </div>;\n  }\n}\n\nclass LevelSettingsModal extends Component {\n  constructor(props) {\n    super(props);\n\n    this.closeModal = this.closeModal.bind(this);\n    this.updateSettings = this.updateSettings.bind(this);\n    this.state = {\n      'title': props.level.name,\n    }\n  }\n\n  closeModal() {\n    window.modal.close();\n  }\n\n  handleChange(id, e) {\n    this.setState({\n      [id]: e.target.value,\n    });\n  }\n\n  updateSettings(e) {\n    const title = this.state.title;\n    if (title == this.props.level.name) {\n      return this.closeModal();\n    }\n    var $btn = $(e.target);\n    $btn.attr('disabled', 'disabled').addClass('loading-spinner-after loading-spinner-m');\n\n    $.ajax({\n      url: '/ajax/level/title_edit',\n      method: 'POST',\n      data: {\n        title,\n        level_id: this.props.level.id,\n      },\n      error: function() {\n        alert('Something went wrong when trying to update the level');\n      },\n      success: function() {\n        this.props.updateTitle && this.props.updateTitle(title);\n        this.closeModal();\n      }.bind(this),\n      complete: function(){\n        $btn.removeAttr('disabled').removeClass('loading-spinner-after loading-spinner-m');\n      }\n    });\n  }\n\n  render() {\n    return <div className=\"vcenter settings learn-settings\">\n      <div className=\"form\">\n        <div>\n          <label htmlFor=\"title\">{window.I18N['edit_level_title']}:&emsp;</label>\n          <input\n            id=\"title\"\n            type=\"text\"\n            defaultValue={this.props.level.name}\n            onChange={this.handleChange.bind(this, 'title')}\n            autoComplete=\"off\"\n          />\n        </div>\n      </div>\n      <div className=\"btn-group\">\n        <button className=\"btn\" onClick={this.closeModal}>{window.I18N['cancel']}</button>\n        <button className=\"btn green\" onClick={this.updateSettings}>{window.I18N['save']}</button>\n      </div>\n    </div>\n  }\n}\n\nclass EditLevel extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      show: false,\n      isLoading: false,\n      content: '',\n      isDeleted: false,\n      name: props.level.name,\n    };\n    this.toggleContent = this.toggleContent.bind(this);\n    this.deleteLevel = this.deleteLevel.bind(this);\n    this.toggleEditTitle = this.toggleEditTitle.bind(this);\n    this.onCloseEditTitle = this.onCloseEditTitle.bind(this);\n    this.updateTitle = this.updateTitle.bind(this);\n    this.showEditTtitle = false;\n  }\n\n  componentDidMount() {\n    if(this.props.show) {\n      this.getData();\n    }\n  }\n\n  shouldComponentUpdate(nextProps, nextState) {\n    return !window.objectsAreEqual(nextState, this.state);\n  }\n\n  toggleContent() {\n    if(!this.state.show) {\n      this.getData();\n\n    } else {\n      this.setState({\n        show: !this.state.show,\n      });\n    }\n  }\n\n  onGetDataSuccess(data) {\n    var content = '';\n    if(this.props.level.pool_id) {\n      var $div = $('.table-container', data.rendered);\n      content = $div.get(0).outerHTML;\n\n      var newRowTemplate = $div.find('tr').last().get(0).outerHTML;\n      this.props.setNewRow(newRowTemplate);\n\n    } else {\n      var $div = $('.multimedia-edit', data.rendered);\n\n      $('*[id]', $div).attr('id', null);\n\n      content = `<div class=\"multimedia-edit\">\n        <nav>\n          <ul class=\"multimedia-preview__tabs\">\n            <li class=\"multimedia-preview__tab multimedia-preview__tab--edit active\">Edit</li>\n            <li class=\"multimedia-preview__tab multimedia-preview__tab--preview\">Preview</li>\n          </ul>\n        </nav>\n        <div class=\"multimedia-preview__content hide\">\n          <div class=\"multimedia-wrapper\"></div>\n        </div>` + $div.get(0).innerHTML + '</div>';\n\n      this.props.setNewRow();\n    }\n    this.setState({\n      show: true,\n      content,\n    });\n  }\n\n  onGetDataDone() {\n    this.setState({\n      isLoading: false,\n    });\n  }\n\n  onGetDataError() {\n    alert(window.I18N['error']);\n  }\n\n  getData() {\n    this.setState({\n      isLoading: true,\n    });\n\n    $.ajax({\n      url: '/ajax/level/' + this.props.level.id,\n      success: this.onGetDataSuccess.bind(this),\n      error: this.onGetDataError.bind(this),\n      complete: this.onGetDataDone.bind(this),\n    });\n  }\n\n  deleteLevel(e) {\n    if(!confirm(window.I18N.confirm_del_level)) {\n      return;\n    }\n    var $btn = $(e.target);\n    $btn.attr('disabled', 'disabled').addClass('loading-spinner loading-spinner-m');\n\n    $.ajax({\n      url: '/ajax/level/delete',\n      method: 'POST',\n      data: {\n        course_id: window.MEMLIKE.course.id,\n        level_id: this.props.level.id,\n      },\n      headers: {\n        'X-CSRFToken': window.MEMLIKE.course.csrftoken,\n        'X-Referer': window.MEMLIKE.course.referer,\n      },\n      success: function() {\n        this.setState({\n          isDeleted: true,\n        });\n      }.bind(this),\n      error: function() {\n        alert('Something went wrong when trying to delete the level');\n      },\n      complete: function(){\n        $btn.removeAttr('disabled').removeClass('loading-spinner loading-spinner-m');\n      }\n    });\n  }\n\n  onCloseEditTitle() {\n    window.modal.onClose('level-title', null);\n\n    if(!this.showEditTtitle) {\n      return;\n    }\n    this.showEditTtitle = false;\n  }\n\n  updateTitle(name) {\n    this.setState({name});\n  }\n\n  toggleEditTitle() {\n    this.showEditTtitle = !this.showEditTtitle;\n    if(!this.showEditTtitle) {\n      return;\n    }\n    var div = window.modal.getContainer().get(0).querySelector('.modal');\n    div.innerHTML = '';\n\n    render(<LevelSettingsModal level={this.props.level} updateTitle={this.updateTitle} />, div);\n    window.modal.reopen();\n    window.modal.onClose('level-title', this.onCloseEditTitle);\n  }\n\n  render() {\n    if (this.state.isDeleted) {\n      return null;\n    }\n    var level = this.props.level;\n\n    return <div\n      className={'edit-level nicebox' + (this.state.show ? '' : ' collapsed')}\n      data-level-index={this.props.index}\n      data-level-id={level.id}\n      data-pool-id={level.pool_id || ''}\n    >\n      <div className=\"edit-level-actions\">\n        {this.state.isLoading && <span className=\"loading-spinner left\"></span>}\n        {this.state.show && (\n          <div className=\"edit-level-actions-group\">\n            <div className=\"btn-group\">\n\n              <button className=\"edit-title btn action\" title={window.I18N.edit_level_title} onClick={this.toggleEditTitle}>\n                <i className=\"ico ico-grey ico-edit\"></i>\n              </button>\n\n              <button className=\"delete-level btn action\" title={window.I18N.delete_level} onClick={this.deleteLevel}>\n                <i className=\"ico ico-grey ico-trash\"></i>\n              </button>\n            </div>\n\n            <div className=\"btn-group\">\n              <button className=\"generate-audio btn action\" title=\"\">\n                {window.I18N.generate_audio}\n              </button>\n            </div>\n\n            <div className=\"btn-group\">\n              <label className=\"export-level btn action\" title={window.I18N.export_level}>\n                {window.I18N.export_level}\n              </label>\n              <label className=\"import-level btn action\" title={window.I18N.import_level} htmlFor={'import_' + level.id}>\n                <input type=\"file\" id={'import_' + level.id} />\n                {window.I18N.import_level}\n              </label>\n            </div>\n\n            <div className=\"btn-group\">\n              <a className=\"btn action\" href={this.props.url} title={window.I18N.goto_level}>\n                {window.I18N.goto_level}\n              </a>\n            </div>\n          </div>\n        )}\n        <label className=\"toggle action\" onClick={this.toggleContent}>\n          <span className=\"ico ico-grey ico-arr-down\"></span>\n        </label>\n      </div>\n\n      <div className=\"edit-level-label\">\n        <label>{this.state.name || window.I18N['level_default_title']}</label>\n        {!level.pool_id && <span>&nbsp;(multimedia)</span>}\n      </div>\n\n      {this.state.show && <div className=\"edit-level-content\" dangerouslySetInnerHTML={{__html: this.state.content}}></div>}\n    </div>;\n  }\n}\n\nclass ColumnSettingsModal extends Component {\n  constructor(props) {\n    super(props);\n\n    this.closeModal = this.closeModal.bind(this);\n    this.updateSettings = this.updateSettings.bind(this);\n    this.deleteColumn = this.deleteColumn.bind(this);\n    this.state = {\n      label: this.props.label,\n    };\n  }\n\n  closeModal() {\n    window.modal.close();\n  }\n\n  handleChange(id, e) {\n    this.setState({\n      [id]: e.target.value,\n    });\n  }\n\n  updateSettings(e) {\n    const label = this.state.label;\n    if (label == this.props.label) {\n      return this.closeModal();\n    }\n    var $btn = $(e.target);\n    $btn.attr('disabled', 'disabled').addClass('loading-spinner-after loading-spinner-m');\n\n    $.ajax({\n      url: '/ajax/level/column_edit',\n      method: 'POST',\n      data: {\n        pool_id: this.props.poolID,\n        column_key: this.props.columnKey,\n        label,\n        column_structure: this.props.columnStructure,\n      },\n      error: function() {\n        alert('Something went wrong when trying to update the level');\n      },\n      success: function() {\n        this.props.updateTitle && this.props.updateTitle(label);\n        this.closeModal();\n      }.bind(this),\n      complete: function(){\n        $btn.removeAttr('disabled').removeClass('loading-spinner-after loading-spinner-m');\n      }\n    });\n  }\n\n  deleteColumn(e) {\n    if (!confirm(window.I18N.confirm_del_column)) {\n      return;\n    }\n    var $btn = $(e.target);\n    $btn.attr('disabled', 'disabled').addClass('loading-spinner-before loading-spinner-m');\n\n    $.ajax({\n      url: '/ajax/level/column_remove',\n      method: 'POST',\n      data: {\n        pool_id: this.props.poolID,\n        column_key: this.props.columnKey,\n        column_structure: this.props.columnStructure,\n      },\n      success: function(){\n        this.props.deleteColumn && this.props.deleteColumn();\n        this.closeModal();\n      }.bind(this),\n      error: function(xhr) {\n        $btn.removeAttr('disabled').removeClass('loading-spinner-before loading-spinner-m');\n\n        alert(window.I18N['error']);\n\n        console.error(xhr);\n      },\n      complete: function() {\n        this.setState({confirmDelete: false});\n      }.bind(this),\n    });\n  }\n\n  render() {\n    return <div className=\"vcenter settings learn-settings\">\n      <div className=\"form\">\n        <div>\n          <label htmlFor=\"label\">{window.I18N['edit_level_title']}:&emsp;</label>\n          <input\n            id=\"label\"\n            type=\"text\"\n            defaultValue={this.props.label}\n            onChange={this.handleChange.bind(this, 'label')}\n            autoComplete=\"off\"\n          />\n        </div>\n      </div>\n      <div className=\"actions\">\n        <div className=\"btn-group\">\n          <button className=\"btn danger\" title={window.I18N.delete_course} onClick={this.deleteColumn}>\n            <i className=\"ico ico-white ico-trash\"></i>\n          </button>\n          <button className=\"btn\" onClick={this.closeModal}>{window.I18N['cancel']}</button>\n          <button className=\"btn green\" onClick={this.updateSettings}>{window.I18N['save']}</button>\n        </div>\n      </div>\n    </div>\n  }\n}\n\n//+--------------------------------------------------------\n//| Events\n//+--------------------------------------------------------\n\nvar isInit  = false,\n    focused = false,\n    altInit = false,\n    thingsRowTemplate = '';\n\nfunction bindEditEvents(tpl) {\n  if (tpl) {\n    thingsRowTemplate = tpl;\n  }\n  if(isInit) {\n    return;\n  }\n  isInit = true;\n  init();\n\n  function init() {\n    $('#edit-levels')\n\n    // New row\n    .on('focus', 'input', focus_input)\n    .on('blur', '.adding input.wide', blur_input_adding)\n    .on('focus', '.adding tr:last-child input.wide', focus_lastRow)\n\n    // Update cell\n    .on('click', 'div.text', click_cell)\n    .on('keyup', 'input.wide', type_cell)\n    .on('blur', '.things input.wide', blur_input_thing)\n\n    .on('click', '.multimedia-edit button', click_saveMultimedia)\n\n    // Preview multimedia\n    .on('click', 'li.multimedia-preview__tab', click_multimediaPreviewToggle)\n\n    // Update alternatives\n    .on('click', '.edit-alts', click_editAlt)\n\n    // Update attachments\n    .on('change', '.things input[type=\"file\"]', send_file)\n    .on('click', '.dropdown-toggle', click_displayFiles)\n    .on('click', '.dropdown-row .ico-trash', click_removeFile)\n    .on('click', '.audio-player', click_audio)\n\n    // Delete row\n    .on('click', '.ico-close', click_deleteRow)\n\n    // Import/export\n    .on('click', '.export-level', click_exportLevel)\n    .on('change', '.import-level input', send_importLevel)\n    .on('click', '.generate-audio', AudioUploader.click_generateAudio)\n    .on('click', 'th[data-key] .ico-edit', click_editColumn);\n  }\n\n  //+---------------------------------------------------------------------------\n  // Remember current input focused\n  function focus_input() {\n    focused = this;\n  }\n\n  //+---------------------------------------------------------------------------\n  // On blur cell in adding tbody: add row\n  function blur_input_adding() {\n    focused = false;\n\n    // Retrieve the row datas\n    var $tr  = $(this).closest('tr'),\n        data = {},\n        empty = true;\n\n    $tr.find('td[data-key]').each(function(){\n      var val = $(this).find('input').val();\n      if(val) {\n        empty = false;\n      }\n      data[$(this).data('key')] = val;\n    });\n    if(empty) {\n      return;\n    }\n    // Memrise won't add data unless both columns have values\n    if(data['1'] == '' || data['2'] == '') {\n      return;\n    }\n\n    // Check if we changed row or just cell of the row\n    setTimeout(function(){\n      if(focused && $(focused).closest('tr').is($tr)) {\n        return;\n      }\n      $tr.addClass('disabled');\n\n      // data: { 1: \"valcolA\", 2: \"valcolB\", 3: undefined }\n      addRow($tr, data);\n    }, 100);\n  }\n\n  // POST new row\n  function addRow($tr, data, callback){\n    var $level  = $tr.closest('.edit-level'),\n        levelId = $level.data('level-id');\n\n    if (!levelId) {\n      console.error('Add row error: couldnt find idLevel');\n      return;\n    }\n    $.ajax({\n      url: '/ajax/level/' + levelId + '/add',\n      method: 'POST',\n      data: {\n        csrftoken: window.MEMLIKE.course.csrftoken,\n        referer: window.MEMLIKE.course.referer,\n        data: JSON.stringify(data)\n      },\n      success: function(json){\n        var html   = json.rendered_thing,\n            $newTr = $(html).appendTo($('.things', $level));\n\n        $tr.remove();\n        callback && callback('success', levelId, $newTr);\n      },\n      error: function(xhr){\n        alert(window.I18N['error']);\n\n        console.error(xhr);\n        $tr.removeClass('disabled');\n        callback && callback('error', levelId, $tr);\n      },\n    });\n  }\n\n  // Import rows: handle file upload from URL\n  async function downloadFromUrls($tr, levelId, uploads) {\n    var thingId = $tr.data('thing-id');\n\n    for(var i=0; i<uploads.length; i++) {\n      var upload  = uploads[i],\n          cellId  = upload[0],\n          $column = $tr.children('[data-key=\"' + cellId + '\"]');\n\n      await downloadFromUrl($column, thingId, cellId, upload);\n    }\n  }\n  function downloadFromUrl($column, thingId, cellId, upload) {\n    var name    = upload[1],\n        url     = upload[2],\n        mime    = upload[3];\n\n    return fetch(url).then(res => res.blob()).then(blob => {\n      var file = new File([blob], name, {type: mime});\n\n      return new Promise((resolve, reject) => {\n        uploadFile($column, cellId, thingId, file, resolve, reject);\n      });\n    });\n  }\n\n  //+---------------------------------------------------------------------------\n  // Focus last row: add a new row\n  function focus_lastRow(){\n    $(this).closest('.adding').append(thingsRowTemplate);\n  }\n\n  //+---------------------------------------------------------------------------\n  // Click on cell: display input\n  function click_cell() {\n    if(this.firstElementChild) {\n      return;\n    }\n    var input       = document.createElement('input');\n    input.value     = this.innerHTML;\n    input.type      = 'text';\n    input.className = 'wide';\n    this.appendChild(input);\n    input.focus();\n  }\n\n  //+---------------------------------------------------------------------------\n  // On enter: focus next row\n  function type_cell(e){\n    if(e.which != 13) {\n      return;\n    }\n    var $tr     = $(e.target).closest('tr'),\n        $nextTr = $tr.next('tr');\n\n    if($nextTr.length == 0) {\n      $nextTr = $tr.closest('tbody').next('tbody').children(':not(.header)').first();\n      $nextTr.find('input.wide').first().focus();\n    } else {\n      $nextTr.find('div.text, input.wide').first().trigger('click').focus();\n    }\n  }\n\n  //+---------------------------------------------------------------------------\n  // On click \"alternatives\": edit alternatives\n  function click_editAlt(e) {\n    e.preventDefault();\n\n    var $btn    = $(e.target),\n        thingId = $btn.closest('.thing').data('thing-id'),\n        cellId  = $btn.closest('.column').data('key');\n\n    $.ajax({\n      url: '/ajax/level/' + thingId + '/alt',\n      method: 'POST',\n      data: {\n        csrftoken: window.MEMLIKE.course.csrftoken,\n        referer: window.MEMLIKE.course.referer\n      },\n      success: function(data) {\n        var alts = data.thing.columns[cellId].alts,\n            html = `<div class=\"vcenter alts\">\n              ${alts.map((alt) => `<div class=\"alt\">\n                <input type=\"text\" name=\"${alt.id}\" value=\"${alt.val}\" />\n                <button type=\"button\" class=\"alt-action\"></button>\n              </div>`).join('')}\n\n              <div class=\"alt\">\n                <input type=\"text\" value=\"\" />\n                <button type=\"button\" class=\"alt-action\"></button>\n              </div>\n            </div>\n\n            <div class=\"alt-actions\">\n              <button class=\"btn alt-cancel\">Annuler</button>\n              <button class=\"btn active alt-save\" data-cell=\"${cellId}\" data-thing=${thingId}>Sauvegarder</button>\n            </div>`;\n\n        window.modal.open(html);\n        bindAltEvents();\n      }\n    });\n  }\n\n  function bindAltEvents() {\n    if(altInit) {\n      return;\n    }\n    altInit = true;\n\n    $('#modal')\n    .on('click', '.alt-cancel', function(){ window.modal.close(); })\n    .on('click', '.alt-action', click_altAction)\n    .on('click', '.alt-save', click_altSave);\n  }\n\n  // Click alt action: last row = add new, others = remove current\n  function click_altAction() {\n    var $alt  = $(this).closest('.alt'),\n        $alts = $(this).closest('.alts');\n\n    if($alts.children().last().is($alt)) {\n      $alts.append(`<div class=\"alt\">\n        <input type=\"text\" value=\"\" />\n        <button type=\"button\" class=\"alt-action\"></button>\n      </div>`);\n    } else {\n      $alt.remove();\n    }\n  }\n\n  // Click alt save: save modal content and close\n  function click_altSave() {\n    var cellId  = $(this).data('cell'),\n        thingId = $(this).data('thing'),\n        alts    = [];\n\n    $('#modal input').each(function(){\n      if(this.value.trim()) {\n        alts.push(this.value.trim());\n      }\n    });\n\n    $.ajax({\n      url: '/ajax/level/' + thingId + '/alt_edit',\n      method: 'POST',\n      data: {\n        csrftoken: window.MEMLIKE.course.csrftoken,\n        referer: window.MEMLIKE.course.referer,\n        alts: JSON.stringify(alts),\n        cell_id: cellId,\n      },\n      success: function() {\n        window.modal.close();\n      }\n    });\n  }\n\n  //+---------------------------------------------------------------------------\n  // On click \"delete\": delete row\n  function click_deleteRow(e){\n    e.preventDefault();\n    if(confirm(window.I18N.confirm_del_row)) {\n      removeRow($(e.target).closest('tr'));\n    }\n  }\n\n  function removeRow($tr){\n    var $level  = $tr.closest('.edit-level'),\n        thingid = $tr.data('thing-id'),\n        levelid = $level.data('level-id');\n\n    $.ajax({\n      url: '/ajax/level/' + levelid + '/remove',\n      method: 'POST',\n      data: {\n        csrftoken: window.MEMLIKE.course.csrftoken,\n        referer: window.MEMLIKE.course.referer,\n        thing_id: thingid,\n      },\n      success: function(){\n        $tr.remove();\n      },\n      error: function(xhr){\n        console.error(xhr);\n        $tr.remove('disabled');\n      }\n    });\n  }\n\n  //+---------------------------------------------------------------------------\n  // On blur cell in things tbody: update cell\n  function blur_input_thing(){\n    var txt  = this.value.trim(),\n        $div = $(this.parentNode);\n\n    if(txt == $div.text()) {\n      $div.text(txt);\n      return;\n    }\n    $div.text(txt);\n\n    var thingId = $div.closest('.thing').data('thing-id'),\n        cellId  = $div.closest('.column').data('key');\n\n    updateCell(thingId, cellId, txt);\n  }\n\n  // POST new cell value\n  function updateCell(thingId, cellId, txt) {\n    if (!txt) {\n      txt = ' ';\n    }\n    $.ajax({\n      url: '/ajax/level/' + thingId + '/edit',\n      method: 'POST',\n      data: {\n        csrftoken: window.MEMLIKE.course.csrftoken,\n        referer: window.MEMLIKE.course.referer,\n        cell_id: cellId,\n        cell_value: txt,\n      },\n      error: function(){\n        alert('Something went wrong when trying to update cell');\n      }\n    });\n  }\n\n  //+---------------------------------------------------------------------------\n  // On send file: upload file\n  function send_file(){\n    var $column = $(this).closest('.column'),\n        cellId  = $column.data('key'),\n        thingId = $(this).closest('.thing').data('thing-id'),\n        file    = this.files[0];\n\n    uploadFile($column, cellId, thingId, file);\n  }\n\n  function uploadFile($column, cellId, thingId, file, resolve=null, reject=null) {\n    var fd = new FormData();\n    fd.append('file', file);\n    fd.append('csrftoken', window.MEMLIKE.course.csrftoken);\n    fd.append('referer', window.MEMLIKE.course.referer);\n    fd.append('cell_id', cellId);\n\n    $.ajax({\n      url: '/ajax/level/' + thingId + '/upload',\n      data: fd,\n      processData: false,\n      contentType: false,\n      type: 'POST',\n      success: function(data){\n        if(data.message) {\n          alert(data.message);\n        }\n        $column.replaceWith(data.rendered);\n        resolve && resolve($column);\n      },\n      error: function(){\n        reject && reject($column);\n      },\n    });\n  }\n\n  //+---------------------------------------------------------------------------\n  // On click files: display attachments\n  function click_displayFiles(e) {\n    var div = e.target.nextElementSibling;\n    div.innerHTML = div.innerHTML.replace(/ src=\"#\"/g, '')\n                                 .replace(/ data-url=\"/g, ' src=\"');\n  }\n\n  // On click dropdown content\n  function click_audio(e) {\n    e.preventDefault();\n    e.stopPropagation();\n\n    window.audioPlayer && window.audioPlayer.play.call(e.target, e);\n  }\n\n  //+---------------------------------------------------------------------------\n  // On click remove file: remove attachment\n  function click_removeFile(e){\n    e.preventDefault();\n    e.stopPropagation();\n\n    if(!confirm(window.I18N.confirm_del_file)) {\n      return;\n    }\n    removeFile($(e.target));\n  }\n\n  function removeFile($btn) {\n    var fileId  = $btn.closest('.dropdown-row').data('file-id'),\n        $column = $btn.closest('.column'),\n        cellId  = $column.data('key'),\n        thingId = $btn.closest('.thing').data('thing-id');\n\n    $.ajax({\n      url: '/ajax/level/' + thingId + '/upload_remove',\n      data: {\n        'csrftoken': window.MEMLIKE.course.csrftoken,\n        'referer': window.MEMLIKE.course.referer,\n        'cell_id': cellId,\n        'file_id': fileId,\n      },\n      type: 'POST',\n      success: function(data){\n        if(data.message) {\n          alert(data.message);\n        }\n        $column.replaceWith(data.rendered);\n      }\n    });\n  }\n\n  //+---------------------------------------------------------------------------\n  // On click save: update multimedia content\n  function click_saveMultimedia() {\n    var $btn = $(this);\n    $btn.attr('disabled', 'disabled').addClass('loading-spinner-after');\n\n    var $level = $btn.closest('.edit-level');\n    var levelId = $level.data('level-id');\n    $.ajax({\n      url: '/ajax/level/' + levelId + '/edit_multimedia',\n      method: 'POST',\n      data: {\n        csrftoken: window.MEMLIKE.course.csrftoken,\n        referer: window.MEMLIKE.course.referer,\n        txt: $btn.prev().val(),\n        course_id: window.MEMLIKE.course.id,\n        level_index: $level.data('level-index'),\n      },\n      error: function() {\n        alert('Something went wrong when trying to update the content');\n      },\n      complete: function(){\n        $btn.removeAttr('disabled').removeClass('loading-spinner-after');\n      }\n    });\n  }\n\n  function click_multimediaPreviewToggle(e) {\n\n    // Toggle current tab\n    var $btn       = $(e.target),\n        isPreview  = $btn.hasClass('multimedia-preview__tab--preview');\n\n    $btn.addClass('active')\n        .siblings()\n        .removeClass('active');\n\n    // Show/hide preview\n    var $container = $btn.closest('.multimedia-edit'),\n        $textarea  = $('textarea', $container),\n        $preview   = $('.multimedia-preview__content', $container);\n\n    if(isPreview) {\n      var html = window.markdown.decode($textarea.val());\n\n      $preview.children(':first').html(html);\n      $preview.removeClass('hide');\n      $textarea.addClass('hide');\n    } else {\n      $preview.addClass('hide');\n      $textarea.removeClass('hide');\n    }\n  }\n\n  //+---------------------------------------------------------------------------\n  // Import/export\n  function click_exportLevel() {\n    var $level     = $(this).closest('.edit-level'),\n        levelId    = $level.data('level-id'),\n        $table     = $level.find('table'),\n        csvContent = exportThings($table);\n\n    window.download(csvContent, window.MEMLIKE.course.title + '_' + levelId + '.csv', 'text/csv;encoding:utf-8');\n  }\n\n  function exportThings($table) {\n    var row        = [],\n        csvContent = '';\n\n    // Get headers\n    $table.children('.columns').find('.column,.attribute').each(function(){\n      row.push($(this).text().trim());\n    });\n    csvContent += exportCsv(row);\n\n    // Get rows\n    $table.children('.things').children().each(function(){\n      var empty = true;\n\n      row = [];\n\n      // Get columns\n      $(this).children('.column,.attribute').each(function(){\n        var $col = $(this),\n            txt  = '';\n\n        // Text\n        if($col.hasClass('text')) {\n          txt = $col.find('.text').text().trim();\n\n        // Image attachment\n        } else if($col.hasClass('image')) {\n          var list = [];\n\n          // Get list of images\n          $col.find('.images').children('.dropdown-row').each(function(){\n            var $item = $(this).find('img'),\n                url   = $item.attr('data-url');\n\n            if(!url) {\n              url = $item.attr('src');\n            }\n            if(url && url != '#') {\n              var filename = url.substring(url.lastIndexOf('/')+1);\n              list.push(filename + ' (' + url + ')');\n            }\n          });\n          txt = list.join(',');\n\n        } else if($col.hasClass('audio')) {\n          var list = [];\n\n          // Get list of audios\n          $col.find('.audios').children('.dropdown-row').each(function(){\n            var $item = $(this).find('a'),\n                url   = $item.attr('data-url');\n\n            if(!url) {\n              url = $item.attr('src');\n            }\n            if(url && url != '#') {\n              var filename = url.substring(url.lastIndexOf('/')+1);\n              list.push(filename + ' (' + url + ')');\n            }\n          });\n          txt = list.join(',');\n        }\n\n        // Add column to row\n        if(txt) {\n          empty = false;\n        }\n        row.push(txt);\n      });\n\n      // Export row\n      if(!empty) {\n        csvContent += exportCsv(row);\n      }\n    });\n    return csvContent;\n  }\n\n  function send_importLevel(e) {\n    if(!e.target.files) {\n      return;\n    }\n    var file = e.target.files[0];\n    if(file.type != 'text/csv') {\n      alert(window.I18N.import_err_ext);\n      return;\n    }\n\n    var reader = new FileReader(),\n        $level = $(this).closest('.edit-level');\n    reader.onload = (function(f) {\n      return function(e) {\n        importFile($level, e.target.result);\n      };\n    })(file);\n\n    reader.readAsText(file);\n  }\n\n  function importFile($level, content) {\n    var data = $.csv.toArrays(content);\n    if(!data.length) {\n      return;\n    }\n\n    var $table        = $level.find('table'),\n        $adding       = $table.children('.adding'),\n        table_headers = [],\n        table_keys    = [],\n        types         = [];\n\n    // Get table headers\n    $table.children('.columns').find('.column,.attribute').each(function(){\n      var $col = $(this),\n          type = 'text';\n\n      if($col.hasClass('image')) {\n        type = 'image';\n      } else if($col.hasClass('audio')) {\n        type = 'audio';\n      }\n      types.push(type);\n\n      table_headers.push($col.text().trim().toLowerCase());\n      table_keys.push($col.data('key'));\n    });\n\n    // Get position of headers in CSV\n    var headers = [],\n        empty   = true;\n    for(var i=0; i<data[0].length; i++) {\n      var header = data[0][i].trim(),\n          k      = table_headers.indexOf(header.toLowerCase());\n\n      if(k==-1) {\n        headers.push(0);\n      } else {\n        empty = false;\n        headers.push({key: table_keys[k], type: types[k], txt: header});\n      }\n    }\n    table_headers = null;\n    table_keys    = null;\n    types         = null;\n\n    // Format rows\n    var rows = [];\n\n    if(!empty) {\n      for(var i=1; i<data.length; i++) {\n        var row        = data[i],\n            row_import = {},\n            row_upload = [];\n\n        // Get row content in the right order\n        for(var j=0; j<row.length; j++) {\n          if(!headers[j]) {\n            continue;\n          }\n          var txt = row[j].trim();\n          if(!txt) {\n            continue;\n          }\n\n          // Add its value\n          var cellId = headers[j].key,\n              type   = headers[j].type;\n\n          if(type == 'text') {\n            row_import[cellId] = txt;\n\n          // Upload its attachments once added\n          } else {\n            var list = txt.split(',');\n            for(var l=0; l<list.length; l++) {\n              var item = list[l];\n\n              // 184839286_180428_1821_37.jpg (https://static.memrise.com/uploads/things/images/184839286_180428_1821_37.jpg)\n              var match = item.match(/^([^(]+)\\(([^)]+)\\)$/),\n                  filename = null,\n                  url = null;\n\n              if (match) {\n                filename = match[1].trim();\n                url = match[2].trim();\n              } else {\n\n                // https://static.memrise.com/uploads/things/images/184839286_180428_1821_37.jpg\n                match = item.match(/^https?:\\/\\/[^)]+\\/[^.]+(\\/[_a-zA-Z0.9]+\\.[a-zA-Z0.9]+)$/);\n                if (match) {\n                  url = item;\n                  filename = match[1].trim();\n                }\n              }\n\n              if (!url || !filename) {\n                continue;\n              }\n              var filename = match[1].trim(),\n                  mime     = '',\n                  ext      = filename.substring(filename.lastIndexOf('.')+1);\n\n              switch(ext) {\n                case 'png':  mime = 'image/png'; break;\n                case 'jpg':  mime = 'image/jpeg'; break;\n                case 'jpeg': mime = 'image/jpeg'; break;\n                case 'gif':  mime = 'image/gif'; break;\n                case 'mp3':  mime = 'audio/mpeg'; break;\n                case 'mp4':  mime = 'video/mp4'; break;\n                case 'aac':  mime = 'audio/aac'; break;\n              }\n              if(!mime) {\n                continue;\n              }\n              row_upload.push([cellId, filename, match[2].trim(), mime]);\n            }\n          }\n        }\n\n        // Create a new table row\n        rows.push({data: row_import, upload: row_upload});\n      }\n    }\n    data = null;\n\n    importPreview(rows, empty ? false : headers, $adding);\n  }\n\n  function importPreview(rows, headers, $adding) {\n    if(!headers) {\n      alert(window.I18N.import_err_empty);\n      return;\n    }\n    var html = '<div class=\"import_preview\">';\n    html += '<button class=\"btn active run_import top\">' + window.I18N.import_level + '</button>';\n    html += '<table>';\n\n    // Display headers\n    html += '<thead><tr>';\n    for(var i=0; i<headers.length; i++) {\n        if(!headers[i]) {\n          continue;\n        }\n      html += '<th>' + headers[i].txt + '</th>';\n    }\n    html += '</tr></thead>';\n\n    // Display rows\n    html += '<tbody>';\n    for(var i=0; i<rows.length; i++) {\n      html += '<tr>';\n\n      var row  = rows[i],\n          data = Object.assign({}, row.data);\n\n      // Bring back upload to data\n      for(var j=0; j<row.upload.length; j++) {\n        var upload  = row.upload[j],\n            cellId  = upload[0],\n            url     = upload[2];\n\n        if(typeof data[cellId] != 'undefined') {\n          data[cellId].push(url);\n        } else {\n          data[cellId] = [url];\n        }\n      }\n\n      // Display data\n      for(var j=0; j<headers.length; j++) {\n        if(!headers[j]) {\n          continue;\n        }\n        var k       = headers[j].key,\n            type    = headers[j].type,\n            content = data[k] || '';\n\n        if(type == 'image') {\n          content = content.map(function(txt){\n            return '<img src=\"' + txt + '\">';\n          }).join('');\n\n        } else if(type == 'audio') {\n          content = content.map(function(txt){\n            return '<audio src=\"' + txt + '\">';\n          }).join('');\n        }\n        html += '<td>' + content + '</td>';\n      }\n      html += '</tr>';\n    }\n    html += '</tbody></table>';\n    html += '<button class=\"btn active run_import bottom\">' + window.I18N.import_level + '</button>';\n    html += '</div>';\n    window.modal.open(html);\n\n    // Close modal = cancel (clear out data)\n    window.modal.onClose('import', function(){\n      rows    = null;\n      headers = null;\n      $adding = null;\n\n      this.onClose('import', null);\n    });\n\n    var run_import = false;\n\n    $('.run_import', window.modal.container).one('click', function(){\n      if(run_import) {\n        return;\n      }\n      run_import = true;\n\n      window.modal.onClose('import', null);\n      window.modal.close();\n\n      while (rows.length) {\n        let batch = rows.splice(0, 10);\n\n        setTimeout(function(){\n          importRows(batch, $adding);\n        }, 0);\n      }\n      rows    = null;\n      headers = null;\n    });\n  }\n\n  /**\n   * List of rows that have been imported,\n   * that do have an upload to handle\n   */\n  function importRowsDone(rows) {\n    if (!window.File) {\n      return;\n    }\n    for(var i=0; i<rows.length; i++) {\n      var row = rows[i],\n          uploads = row.upload;\n\n      downloadFromUrls(row.$tr, row.levelId, row.upload);\n    }\n  }\n\n  function importRows(rows, $adding) {\n    var pending = 0;\n    var callbackRows = [];\n\n    var addCallback = function(data, upload) {\n      pending++;\n\n      return function(status, levelId, $newTr) {\n        pending--;\n        if (status == 'success') {\n          callbackRows.push({data, upload, levelId, $tr: $newTr});\n        }\n        if(pending == 0) {\n          setTimeout(function() {\n            importRowsDone(callbackRows);\n          }, 0);\n        }\n      };\n    };\n\n    for(var i=0; i<rows.length; i++) {\n      var data   = rows[i].data,\n          upload = rows[i].upload,\n          $tr    = $(thingsRowTemplate).appendTo($adding).prev().addClass('disabled');\n\n      for(var k in data) {\n        $tr.children('[data-key=\"' + k + '\"]').find('input').val(data[k]);\n      }\n      var callback = upload ? addCallback(data, upload) : false;\n      addRow($tr, data, callback);\n    }\n  }\n}\n\n/**\n * @param array row\n * @return string\n */\nfunction exportCsv(row) {\n  var txt = '';\n\n  for(var i=0; i<row.length; i++) {\n    if(i > 0) {\n      txt += ',';\n    }\n    if(row[i].indexOf(',') == -1) {\n      txt += row[i];\n    } else {\n      txt += '\"' + row[i].replace(/\\\\/g, '\\\\\\\\').replace(/\"/g, '\"') + '\"';\n    }\n  }\n  return txt + '\\n';\n}\n\n//+------------------------------------------------------\n//|\n//| UPLOAD AUDIO\n//|\n//+------------------------------------------------------\n\nfunction findValue(obj, value) {\n  for(let k in obj) {\n    if(obj.hasOwnProperty(k) && obj[k] == value) {\n      return k;\n    }\n  }\n  return undefined;\n}\n\nvar AudioUploader = {\n\n  /**\n   * Generate audio for the current level\n   */\n  click_generateAudio: function(e) {\n    var $level  = $(this).closest('.edit-level'),\n        table   = $level.find('table').get(0),\n        column1 = table.firstElementChild.querySelector('.column').innerText.trim();\n\n    // Get lang label\n    var languageCode = findValue(window.TTS.langs, column1);\n    if(typeof languageCode == 'undefined') {\n      alert(column1 + \" isn't a recognized language\");\n      return;\n    }\n\n    // Get list of words without audio\n    var things = table.querySelector('.things').children;\n\n    for(let i=0; i<things.length; i++) {\n      let thing   = things[i],\n          word    = thing.querySelector('.column .text').innerText.trim(),\n          $column = $('.audio', thing);\n\n      // Already has an audio?\n      let listAudio = $('.dropdown-toggle', $column).text().trim();\n      if(/^[1-9]/.test(listAudio)) {\n        continue;\n      }\n\n      // If not: generate the audio from Google TTS and upload it\n      AudioUploader.uploadWord({\n        word,\n        $column,\n        thingId: thing.getAttribute('data-thing-id'),\n        cellId : $column.data('key'),\n        url    : AudioUploader.getGoogleTtsUrl(languageCode, word)\n      });\n    }\n  },\n\n  /**\n   * Returns Google TTS url\n   * for the given word and language\n   *\n   * @return string\n   */\n  getGoogleTtsUrl: function(languageCode, word) {\n    const url = `https://translate.google.com/translate_tts?ie=UTF-8&tl=${languageCode || 'en'}&client=tw-ob&q=${encodeURIComponent(word)}&tk=${Math.floor(Math.random() * 1000000)}&ttsspeed=1`;\n\n    const proxy_url = 'https://cors-anywhere.99901dev.workers.dev/?q=' + encodeURIComponent(url);\n\n    return proxy_url;\n  },\n\n  /**\n   * Upload Google TTS to Memrise\n   */\n  uploadWord: function({url, word, thingId, cellId, $column}) {\n    $('.files-add', $column).remove();\n\n    let status = 200;\n\n    fetch(url)\n      .then(res => {\n        status = res.status;\n\n        if(res.status!=200) {\n          return res.text();\n        } else {\n          return res.blob()\n        }\n      })\n      .then(blob => {\n        if(status!=200) {\n          console.error(status, blob);\n          return;\n        }\n        let file = new File([blob], word + '.mp3', {type: 'audio/mpeg'});\n\n        let fd = new FormData();\n        fd.append('cell_id', cellId);\n        fd.append('cell_type', 'column');\n        fd.append('csrftoken', window.MEMLIKE.course.csrftoken);\n        fd.append('referer', window.MEMLIKE.course.referer);\n        fd.append('file', file);\n\n        $.ajax({\n          url: '/ajax/level/' + thingId + '/upload',\n          data: fd,\n          processData: false,\n          contentType: false,\n          type: 'POST',\n          success: function(data){\n            if(data.message) {\n              alert(data.message);\n            }\n            $column.replaceWith(data.rendered);\n          }\n        }); // end ajax\n      }); // end fetch\n  } // end uploadWord\n};\n\n//+---------------------------------------------------------------------------\n// Rename\nfunction click_editColumn(e) {\n  var $column = $(e.target).closest('th'),\n      $span = $('span', $column),\n\n      updateTitle = function(title) {\n        $span.html(title);\n      },\n      deleteColumn = function() {\n        let idx = $column.index();\n\n        $column.closest('table').find('tr').each(function() {\n          $(this).find(`td:eq(${idx}),th:eq(${idx})`).remove();\n        });\n      },\n      columnKey = $column.attr('data-key'),\n      columnStructure = $column.hasClass('attribute') ? 'attribute' : 'column';\n\n  var div = window.modal.getContainer().get(0).querySelector('.modal');\n  div.innerHTML = '';\n\n  render(<ColumnSettingsModal\n    poolID={window.MEMLIKE.course.last_pool_id}\n    columnKey={columnKey}\n    columnStructure={columnStructure}\n    updateTitle={updateTitle}\n    deleteColumn={deleteColumn}\n    label={$span.html().trim()}\n  />, div);\n  window.modal.reopen();\n}\n"]}